// The catalogue of skills Settings › Skills offers to install: `Resources/skills-index.json` (generated by
// tools/skills: every skill with its source, licence, pinned commit and the size and SHA-256 of each file), decoded
// once on first use; without a readable resource the catalogue is empty and the page shows none. `shared` is the
// newest valid index: the bundled one, or a newer copy `DirectoryCatalogs` downloaded from the public index
// repository (it posts `DirectoryCatalogs.didChange` then). No skill file is fetched until the user presses `+` on a skill: `SkillsCatalogInstaller.download` then fetches exactly the listed files from
// raw.githubusercontent.com at the pinned commit, checks every size and hash, and leaves a folder for the ordinary
// import path (SkillImporter.inspect → Review skill → install).
import AntiChatNetwork
import CryptoKit
import Foundation
import OsaurusVendored

public struct SkillsCatalog: Sendable {
    public typealias Category = ComposioCatalog.Category

    public struct File: Sendable, Equatable, Decodable {
        public let path: String
        public let sha256: String
        public let size: Int
        public init(path: String, sha256: String, size: Int) { self.path = path; self.sha256 = sha256; self.size = size }
    }

    public struct Skill: Sendable, Equatable, Decodable, Identifiable {
        /// `<source>/<name>`.
        public let id: String
        /// The folder name it installs under.
        public let name: String
        public let title: String
        public let summary: String
        public let category: String
        public let author: String
        public let license: String
        public let commit: String
        /// `https://raw.githubusercontent.com/<owner>/<repo>/<commit>/<path>/`.
        public let base: String
        public let files: [File]
        /// The rank among the featured skills (1 = first); nil = not one of them.
        public let featured: Int?

        public init(id: String, name: String, title: String, summary: String = "", category: String = "", author: String = "",
                    license: String = "", commit: String = "", base: String = "", files: [File] = [], featured: Int? = nil) {
            self.id = id; self.name = name; self.title = title; self.summary = summary; self.category = category
            self.author = author; self.license = license; self.commit = commit; self.base = base; self.files = files
            self.featured = featured
        }
    }

    /// The day the index was generated (`2026-11-16`); "" = unknown.
    public let generated: String
    /// In display order.
    public let categories: [Category]
    /// Featured skills first (by rank), then by title.
    public let skills: [Skill]
    private let keys: [(title: String, rest: String)]

    /// The index this build ships.
    public static let bundled = SkillsCatalog(data: Bundle.module.url(forResource: "skills-index", withExtension: "json")
        .flatMap { try? Data(contentsOf: $0) })

    /// The newest valid index: a downloaded one that is newer than `bundled`, else `bundled`.
    public static var shared: SkillsCatalog { DirectoryCatalogs.live?.skills ?? bundled }

    /// The sources, licences and attribution of the catalogue's skills (tools/skills/NOTICE.md), when bundled.
    public static var notice: String? {
        Bundle.module.url(forResource: "skills-NOTICE", withExtension: "md").flatMap { try? String(contentsOf: $0, encoding: .utf8) }
    }

    /// `data` = the JSON file; nil or unreadable = an empty catalogue.
    public init(data: Data?) {
        struct Index: Decodable { let generated: String?; let categories: [Category]; let skills: [Skill] }
        let index = data.flatMap { try? JSONDecoder().decode(Index.self, from: $0) }
        self.init(categories: index?.categories ?? [], skills: index?.skills ?? [], generated: index?.generated ?? "")
    }

    public init(categories: [Category], skills: [Skill], generated: String = "") {
        self.generated = generated
        let sorted = skills.sorted {
            ($0.featured ?? .max, ComposioCatalog.fold($0.title), $0.id) < ($1.featured ?? .max, ComposioCatalog.fold($1.title), $1.id)
        }
        self.categories = categories
        self.skills = sorted
        keys = sorted.map { (ComposioCatalog.fold($0.title), ComposioCatalog.fold("\($0.name) \($0.summary) \($0.author)")) }
    }

    public var isEmpty: Bool { skills.isEmpty }

    public func skills(in category: String) -> [Skill] { skills.filter { $0.category == category } }

    /// The skills whose title, name, summary or author contains `query` (case and accents ignored): titles that
    /// start with it first, then titles that contain it, then the rest. An empty query = none.
    public func search(_ query: String) -> [Skill] {
        let q = ComposioCatalog.fold(query.trimmingCharacters(in: .whitespacesAndNewlines))
        guard !q.isEmpty else { return [] }
        var tiers: [[Skill]] = [[], [], []]
        for (i, k) in keys.enumerated() {
            if k.title.hasPrefix(q) { tiers[0].append(skills[i]) }
            else if k.title.contains(q) { tiers[1].append(skills[i]) }
            else if k.rest.contains(q) { tiers[2].append(skills[i]) }
        }
        return tiers.flatMap { $0 }
    }
}

/// Fetches one catalogue skill into a temp folder, or nothing at all.
public enum SkillsCatalogInstaller {
    public enum Failure: Error, Equatable {
        /// The index entry itself is not acceptable (name, base URL, a file path, the limits, no SKILL.md).
        case entry(String)
        /// A file could not be fetched (the HTTP status; 0 = no answer).
        case fetch(path: String, status: Int)
        case sizeMismatch(path: String)
        case hashMismatch(path: String)

        /// The download itself failed (as opposed to: what arrived, or the listing, is not to be trusted).
        public var isNetwork: Bool { if case .fetch = self { true } else { false } }
    }

    /// One GET: the body and the HTTP status.
    public typealias Loader = @Sendable (URL) async throws -> (Data, Int)

    public static let host = "raw.githubusercontent.com"

    public static let gated: Loader = { url in
        let (data, response) = try await NetworkGate.gated(.catalog).data(from: url)
        return (data, (response as? HTTPURLResponse)?.statusCode ?? 0)
    }

    /// Where `file` of `skill` is fetched from: `base + path`, only ever https on raw.githubusercontent.com, under
    /// the base's own path at the pinned commit. Throws for anything else (an absolute path, `..`, a query, …).
    public static func url(_ skill: SkillsCatalog.Skill, _ file: SkillsCatalog.File) throws -> URL {
        let hex = CharacterSet(charactersIn: "0123456789abcdef")
        guard skill.commit.count == 40, skill.commit.unicodeScalars.allSatisfy(hex.contains),
              let base = URLComponents(string: skill.base), base.scheme == "https", base.host == host, base.port == nil,
              base.user == nil, base.password == nil, base.query == nil, base.fragment == nil,
              base.path.hasSuffix("/"), base.path.contains("/\(skill.commit)/"), !base.path.contains("/../"), !base.path.contains("//")
        else { throw Failure.entry("base") }
        let parts = file.path.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
        guard !file.path.isEmpty, !file.path.contains("\\"), !file.path.unicodeScalars.contains(where: { $0.value < 0x20 }),
              parts.allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else { throw Failure.entry(file.path) }
        var c = base
        c.path = base.path + file.path
        guard let url = c.url, url.scheme == "https", url.host() == host, url.path().hasPrefix(base.percentEncodedPath) else {
            throw Failure.entry(file.path)
        }
        return url
    }

    /// Downloads every file of `skill` into `<temp>/<uuid>/<name>/` and returns that folder; the caller removes its
    /// parent when done. Every file must have the listed size and SHA-256; on any failure nothing is left behind.
    public static func download(_ skill: SkillsCatalog.Skill, policy: SkillImportPolicy = SkillImporter.policy,
                                temp: URL = FileManager.default.temporaryDirectory, loader: Loader = gated) async throws -> URL {
        let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyz0123456789-_")
        guard (1...64).contains(skill.name.count), skill.name.unicodeScalars.allSatisfy(allowed.contains) else { throw Failure.entry("name") }
        guard skill.files.contains(where: { $0.path == "SKILL.md" }), skill.files.count <= policy.maxEntryCount,
              Set(skill.files.map { $0.path.lowercased() }).count == skill.files.count,
              skill.files.allSatisfy({ $0.size >= 0 && Int64($0.size) <= policy.maxEntryBytes }),
              Int64(skill.files.reduce(0) { $0 + $1.size }) <= policy.maxArchiveBytes else { throw Failure.entry("files") }
        let urls = try skill.files.map { try url(skill, $0) }  // every path is checked before the first request
        let fm = FileManager.default
        let work = temp.appendingPathComponent("antichat-skill-catalog-\(UUID().uuidString)", isDirectory: true)
        let root = work.appendingPathComponent(skill.name, isDirectory: true)
        do {
            try fm.createDirectory(at: root, withIntermediateDirectories: true)
            for (file, url) in zip(skill.files, urls) {
                try Task.checkCancellation()
                // `standardized`, not `standardizedFileURL`: that one drops `/private` from a folder that exists and
                // keeps it for a file that does not yet, so every file was refused under /private/tmp or /private/var/tmp.
                let target = root.appendingPathComponent(file.path).standardized
                guard target.path.hasPrefix(root.standardized.path + "/") else { throw Failure.entry(file.path) }
                let answer: (Data, Int)
                do { answer = try await loader(url) } catch is CancellationError { throw CancellationError() } catch {
                    throw Failure.fetch(path: file.path, status: 0)
                }
                guard answer.1 == 200 else { throw Failure.fetch(path: file.path, status: answer.1) }
                guard answer.0.count == file.size else { throw Failure.sizeMismatch(path: file.path) }
                let digest = SHA256.hash(data: answer.0).map { String(format: "%02x", $0) }.joined()
                guard digest == file.sha256.lowercased() else { throw Failure.hashMismatch(path: file.path) }
                try fm.createDirectory(at: target.deletingLastPathComponent(), withIntermediateDirectories: true)
                try answer.0.write(to: target)
            }
            return root
        } catch {
            try? fm.removeItem(at: work)
            throw error
        }
    }
}
